WITH src AS (SELECT * FROM order_items WHERE order_id = 40), summary AS (SELECT CASE WHEN unit_price >= 400 THEN 'high' WHEN unit_price >= 110 THEN 'mid' ELSE 'low' END AS unit_price_bucket, ROUND(AVG(quantity), 2) AS avg_quantity, ROUND(AVG(unit_price), 2) AS avg_unit_price FROM src GROUP BY CASE WHEN unit_price >= 400 THEN 'high' WHEN unit_price >= 110 THEN 'mid' ELSE 'low' END) SELECT unit_price_bucket, avg_quantity, avg_unit_price FROM summary WHERE avg_quantity < 40;
